"""Task model (SPEC §1): data size, CPU cycles, deadline, priority.

Units: data_bits in bits, cycles in CPU cycles, deadline_s in seconds.
All distributions are synthetic placeholders documented in environment/README.md.
"""

from __future__ import annotations

from dataclasses import dataclass

from environment.config import LOAD_SIZE_MULT


@dataclass
class Task:
    """One offloadable compute task generated by a vehicle."""

    task_id: int
    requester_id: int
    arrival_s: float
    data_bits: float
    cycles: float
    deadline_s: float
    priority: int  # 1 (low) .. 3 (high)

    def validate(self) -> None:
        if self.data_bits <= 0 or self.cycles <= 0 or self.deadline_s <= 0:
            raise ValueError("task size, cycles and deadline must be > 0")
        if self.priority not in (1, 2, 3):
            raise ValueError("priority must be 1, 2 or 3")


class TaskGenerator:
    """Seeded synthetic task stream.

    - Inter-arrival gaps ~ Exponential(mean by load level).
    - Data size ~ Uniform(1, 10) Mbit × load multiplier.
    - Intensity ~ Uniform(200, 2000) cycles/bit; cycles = bits × intensity.
    - Deadline = slack × (cycles / requester_freq); slack ~ Uniform(1.5, 3.0).
    - Priority ~ Categorical {1: 0.5, 2: 0.3, 3: 0.2}.
    """

    def __init__(self, rng, task_load: str, mean_gap_s: float) -> None:
        self._rng = rng
        self._size_mult = LOAD_SIZE_MULT[task_load]
        self._mean_gap = mean_gap_s

    def next(self, task_id: int, requester_id: int, now_s: float, requester_freq_hz: float) -> Task:
        gap = float(self._rng.exponential(self._mean_gap))
        data_bits = float(self._rng.uniform(1e6, 10e6)) * self._size_mult
        intensity = float(self._rng.uniform(200.0, 2000.0))
        cycles = data_bits * intensity
        slack = float(self._rng.uniform(1.5, 3.0))
        deadline_s = slack * cycles / requester_freq_hz
        priority = int(self._rng.choice([1, 2, 3], p=[0.5, 0.3, 0.2]))
        task = Task(task_id, requester_id, now_s + gap, data_bits, cycles, deadline_s, priority)
        task.validate()
        return task
